                    "type": "string"
                }
            },
            "type": [
                "object",
                "null"
            ]
        }
    },
    "patternProperties": {
        "^x-": {}
    },
    "properties": {
        "networks": {
            "id": "#/properties/networks",
            "patternProperties": {
                "^[a-zA-Z0-9._-]+$": {
                    "$ref": "#/definitions/network"
