                                            "type": "array",
                                            "minItems": 1,
                                            "items": {
                                                "type": [
                                                    "string",
                                                    "number",
                                                    "boolean",
                                                    "null"
                                                ]
                                            },
                                            "_uniqueItems": true
                                        },
                                        {
                                            "type": "string",
                                            "pattern": "^#/"
                                        }
                                    ]
                                }
                            },
                            "required": [
                                "type"
                            ],
                            "additionalProperties": false
                        }
                    }
                },
