            "description": "A description of the teaser (usually a few sentences). It should typically not have HTML as it is used in metadata, feeds, SERP and social.",
            "pbj": {
                "type": "text",
                "rule": "single"
            }
        },
        "caption": {
            "type": "string",
            "minLength": 0,
            "maxLength": 255,
            "description": "Text to be used to caption the teaser.",
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "cta_text": {
            "type": "string",
            "minLength": 0,
            "maxLength": 255,
            "description": "Text to be used for the call to action.",
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "credit": {
            "type": "string",
            "minLength": 0,
            "maxLength": 255,
            "description": "Text to be used to credit the teaser source.",
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "credit_url": {
            "type": "string",
            "pattern": "^(https?:\\/\\/)?([\\da-z\\.-]+)\\.([a-z\\.]{2,6})([\\/\\w \\.-]*)*\\/?$",
            "description": "URL to be used to link to the teaser source.",
            "pbj": {
                "type": "text",
                "rule": "single",
                "format": "url"
            }
        },
        "gallery_ref": {
            "type": "string",
            "pattern": "^[\\w\\/\\.:-]+$",
            "pbj": {
                "type": "identifier",
                "rule": "single"
            }
        },
        "timeline_ref": {
            "type": "string",
            "pattern": "^[\\w\\/\\.:-]+$",
            "pbj": {
                "type": "identifier",
                "rule": "single"
            }
        },
        "youtube_video_id": {
            "type": "string",
            "pattern": "^[\\w-]+$",
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        },
        "youtube_custom_id": {
            "type": "string",
            "pattern": "^[\\w@#-]+$",
            "pbj": {
                "type": "string",
                "rule": "single"
            }
        }
    },
    "required": [
        "_id",
        "youtube_video_id"
    ],
    "additionalProperties": true
}

